mapper.select:

where slot_id = #{slotId}
  and deleted = 0
order by id asc


where schedule_resource_id = #{scheduleResourceId}
  and deleted = 0
order by slot_id asc, id asc

select count(1)
from competition_scene_resource_slot_group_scope
where slot_id = #{slotId}
  and allowed_group_code = #{groupCode}
  and enabled = 1
  and deleted = 0
